import{_ as o,o as t,c as n,a5 as e}from"./chunks/framework.BEZBAInb.js";const _=JSON.parse('{"title":"看板娘 Kona","description":"","frontmatter":{"title":"看板娘 Kona","order":2},"headers":[],"relativePath":"tc/latest/community/kona.md","filePath":"tc/latest/community/kona.md","lastUpdated":1788455378000}'),r={name:"tc/latest/community/kona.md"};function i(c,a,l,s,d,p){return t(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="周邊-ip-介紹" tabindex="-1">周邊 IP 介紹 <a class="header-anchor" href="#周邊-ip-介紹" aria-label="Permalink to &quot;周邊 IP 介紹&quot;">​</a></h1><h2 id="kona-介紹" tabindex="-1">Kona 介紹 <a class="header-anchor" href="#kona-介紹" aria-label="Permalink to &quot;Kona 介紹&quot;">​</a></h2><p>Kona 是 Konado 的專屬看板娘，以<strong>活潑可愛、充滿元氣</strong>的少女形象為核心。她不僅是品牌視覺的重要符號，也成為使用者與 Konado 之間親和而自然的互動載體。</p><h2 id="kona-形象" tabindex="-1">Kona 形象 <a class="header-anchor" href="#kona-形象" aria-label="Permalink to &quot;Kona 形象&quot;">​</a></h2><p>Kona 的身影貫穿 Konado 的各個場景。無論是啟動畫面、官方網站首頁，還是產品文件，都能透過她的形象為品牌注入鮮活感。隨著 Konado 的版本迭代，Kona 的形象也會同步進化，既貼合新版本的設計風格，也在細節打磨中變得更精緻、更具辨識度。</p><p>通常在 Konado 的<strong>大版本更新</strong>時，Kona 會推出專屬的全新形象。每一款形象都有獨特的設計巧思，既延續她的核心氣質，也為產品增添更多趣味與記憶點。</p><p>當然，在小版本更新時，Kona 也會有一些小變化，例如換上不同季節的服飾，或增加一些小配件，讓形象更加豐富多元。</p><blockquote><p>畫師：<a href="https://github.com/ioniccrystal" target="_blank" rel="noreferrer">ioniccrystal</a> 發布時間：2025-09-15</p></blockquote><p align="center"><img src="https://legacy.godothub.com/kbgirl/kona/kona.png" alt="Kona 2.0 主形象圖" width="300"></p>',9)])])}const m=o(r,[["render",i]]);export{_ as __pageData,m as default};
